fn required<'a>(
    scoped_project: bool,
    always: &'a [&'a str],
    without_scope: &'a [&'a str],
) -> Vec<&'a str> {
    let fields = if scoped_project {
        without_scope
    } else {
        always
    };
    fields.to_vec()
}

fn tool_descriptor(name: &str, description: &str, properties: Value, required: &[&str]) -> Value {
    json!({
        "name": name,
        "description": description,
        "inputSchema": {
            "type": "object",
            "properties": properties,
            "required": required,
            "additionalProperties": false
        }
    })
}
